    id: drawioEditor.id,
    label: 'Draw.io Light',
    kind: 'light',
    colors,
    // Reuse the validated resolver's final system mapping; do not duplicate its precedence.
    effectiveColors: snapshot.forcedColors ? { ...snapshot.effectiveColors } : { ...colors },
  })
}
